import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        nextInt();
        long[] out = new long[n];
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        long previous = 0;
        while (true) {
            String log = next();
            if (log.isEmpty()) break;
            String[] f = log.split(":");
            int v = Integer.parseInt(f[0]);
            long t = Long.parseLong(f[2]);
            if (f[1].equals("start")) {
                if (!stack.isEmpty()) out[stack.peek()] += t - previous;
                stack.push(v);
                previous = t;
            } else {
                out[stack.pop()] += t - previous + 1;
                previous = t + 1;
            }
        }
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) res.append(i > 0 ? " " : "").append(out[i]);
        System.out.println(res);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"bytes"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n := int(nextInt())
	nextInt()
	out := make([]int64, n)
	var stack []int
	var previous int64
	for {
		log := next()
		if len(log) == 0 {
			break
		}
		f := bytes.Split(log, []byte(":"))
		v, _ := strconv.Atoi(string(f[0]))
		t, _ := strconv.ParseInt(string(f[2]), 10, 64)
		if string(f[1]) == "start" {
			if len(stack) > 0 {
				out[stack[len(stack)-1]] += t - previous
			}
			stack = append(stack, v)
			previous = t
		} else {
			out[stack[len(stack)-1]] += t - previous + 1
			stack = stack[:len(stack)-1]
			previous = t + 1
		}
	}
	for i, v := range out {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(v, 10))
	}
	w.WriteByte('\n')
}
